examples.template:
MonarchSectionCard(
    title = {{title}},
    description = {{description}},
    footer = {
        Spacer(Modifier.weight(1f))
        MonarchButton(text = {{action}}, onClick = {}, variant = MonarchButtonVariant.Primary)
    },
) {
    MonarchTextField(
        value = displayName,
        onValueChange = { displayName = it },
        label = {{rows.0.label}},
        helperText = {{rows.0.description}},
        required = {{rows.0.required}},
    )
    MonarchSwitchRow(
        checked = showsStatus,
        onCheckedChange = { showsStatus = it },
        label = {{rows.1.label}},
    )
}

examples.code:
MonarchSectionCard(
    title = "Profile",
    description = "How you appear to your teammates.",
    footer = {
        Spacer(Modifier.weight(1f))
        MonarchButton(text = "Save", onClick = {}, variant = MonarchButtonVariant.Primary)
    },
) {
    MonarchTextField(
        value = displayName,
        onValueChange = { displayName = it },
        label = "Display name",
        helperText = "Shown on comments and assignments.",
        required = true,
    )
    MonarchSwitchRow(
        checked = showsStatus,
        onCheckedChange = { showsStatus = it },
        label = "Show my status",
    )
}

MonarchSectionCard(title = "Danger zone", tone = MonarchTone.Danger) {
    MonarchListRow(
        headlineContent = { Text("Delete workspace") },
        supportingContent = { Text("Removes every project and file. This cannot be undone.") },
        trailingContent = {
            MonarchButton(
                text = "Delete",
                onClick = { /* Open a confirmation. */ },
                variant = MonarchButtonVariant.Danger,
                size = MonarchButtonSize.Sm,
            )
        },
    )
}

Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchSectionCard(
        title = "Billing",
        state = MonarchSectionCardState.Loading,
        labels = MonarchSectionCardLabels(loading = "Loading settings"),
    ) {}
    MonarchSectionCard(
        title = "Billing",
        state = MonarchSectionCardState.Empty,
        emptyMessage = "Ask a workspace owner to change billing.",
        labels = MonarchSectionCardLabels(emptyTitle = "You don’t have access to these settings"),
    ) {}
}
